import {TEAMS,PLAYERS} from './game/kbo-2026.js';
import {prepareRoster,upgradeToV4} from './game/contract/league-fill.js';import {createFinance} from './game/contract/finance.js';
export const teams=TEAMS.map(t=>t.name);
export const marks=TEAMS.map(t=>t.mark);
export const positions=['CF','2B','RF','1B','DH','3B','LF','SS','C'];
const names=['서지훈','김도윤','이준혁','강태오','박건우','한시우','정민재','오태준','윤서진','임현우','백승호','조우진','문성민','신재영','차민석','권도현','장시환','류정우','홍성준','배준서','이건호','양지호','전민규','최준영','송태양','고은성','박지완','나승준','황도경','유하준','김찬우','안재현','우성민','신도현','김태훈','도준호','유정민','하준석','정성우','한도영','서민호','김주원'];
export function seedPlayers(team=0){return names.map((name,i)=>{const pitcher=i>=15&&i<29||i>=37;const ab=110+(i*29+team*13)%150,h=Math.round(ab*(.235+(i*7%105)/1000)),bb=12+i%24,doubles=9+i%12,triples=i%3,hr=3+i%14,tb=h+doubles+triples*2+hr*3;const outs=90+(i*17%240),er=8+i%20;return {id:`${team}-${i}`,name:team?names[(i+team*3)%names.length]:name,team:teams[team],pos:pitcher?(i<20?'SP':'RP'):(positions[i%9]),pitcher,age:21+i%15,no:3+i*2,ovr:61+(i*7+team)%32,pot:Math.min(99,72+(i*5+team)%27),energy:i===3?43:i===6?57:74+i*7%27,group:i<28?'first':i<39?'second':'injured',injury:i>=39?['햄스트링 염좌','어깨 염증','손목 타박상'][i-39]:'',days:i>=39?[5,12,8][i-39]:0,pa:ab+bb+3,ab,h,bb,hr,doubles,triples,k:35+i%36,sb:i%19,attempts:i%19+3,rbi:18+i*3%55,avg:h/ab,obp:(h+bb)/(ab+bb+3),slg:tb/ab,ops:(h+bb)/(ab+bb+3)+tb/ab,babip:(h-hr)/(ab-(35+i%36)-hr+3),iso:(tb-h)/ab,bbRate:bb/(ab+bb+3),kRate:(35+i%36)/(ab+bb+3),g:20+i%33,gs:pitcher&&i<20?12:0,w:i%9,l:i%5,sv:i===27?18:i%3,hld:i%13,outs,ip:Math.floor(outs/3)+(outs%3)/10,ha:Math.floor(outs*.27),er,r:er+3,hp:i%5,era:er*27/outs,whip:(Math.floor(outs*.27)+bb)*3/outs,k9:(35+i%36)*27/outs,bb9:bb*27/outs,war:(i%35)/10};});}
export const STATE_KEY='dugout-prototype-v5',PREV_KEYS=['dugout-prototype-v4','dugout-prototype-v3','dugout-prototype-v2'],LEGACY_KEYS=['dugout-prototype-v1','dugout-active-game-v1'];
// 팀 로스터로 원문 보직 그대로 타순·수비·로테이션·불펜을 짠다. 비는 수비 위치(주로 DH)는 벤치 최고 OVR 타자, 선발이 5명 미만이면 체력 높은 불펜으로 채운다.
export function teamSetup(players){const first=players.filter(p=>p.group==='first'),bat=first.filter(p=>!p.pitcher),arm=first.filter(p=>p.pitcher),field={};for(const p of bat.filter(p=>p.role==='주전'))if(positions.includes(p.pos)&&!field[p.pos])field[p.pos]=p.id;const bench=bat.filter(p=>!Object.values(field).includes(p.id)).sort((a,b)=>b.ovr-a.ovr);for(const pos of positions)if(!field[pos])field[pos]=bench.shift()?.id||null;const order=Object.values(field).filter(Boolean).map(id=>first.find(p=>p.id===id)).sort((a,b)=>b.ovr-a.ovr).map(p=>p.id);const rotation=arm.filter(p=>p.role==='SP').map(p=>p.id);for(const p of arm.filter(p=>!rotation.includes(p.id)&&!['CL','SU'].includes(p.role)).sort((a,b)=>b.ratings.stamina-a.ratings.stamina))if(rotation.length<5)rotation.push(p.id);const rank=p=>p.role==='CL'?0:p.role==='SU'?1:2,bullpen=arm.filter(p=>!rotation.includes(p.id)).sort((a,b)=>rank(a)-rank(b)).map(p=>p.id),roles={};for(const p of arm){if(p.role==='CL')roles[p.id]={role:'마무리',usage:'9회 이후',secondary:'없음'};if(p.role==='SU')roles[p.id]={role:'셋업',usage:'적당히 등판',secondary:'없음'};}return {order,field,rotation,bullpen,roles};}
export function initialState(){const all=structuredClone(PLAYERS),rosters=teams.map((_,i)=>prepareRoster(all.filter(p=>p.teamIndex===i),i)),players=rosters[0],setup=teamSetup(players);return {version:5,players,league:Object.fromEntries(rosters.map((r,i)=>[i,r]).filter(([i])=>i>0)),...setup,strategy:{size:'5인',mode:'체력 우선',next:setup.rotation[0],relief:'중요 상황에서만'},finance:createFinance(),offseason:null};}
export const teamPlayers=(state,i)=>Number(i)===0?state.players:state.league[i];
// 저장 데이터를 읽는다. v1(가상 선수)은 실제 로스터와 대응 관계가 없어 버리고 새로 시작한다.
export function loadState(storage){const legacy=LEGACY_KEYS.some(k=>storage.getItem(k)!==null);for(const k of LEGACY_KEYS)storage.removeItem(k);try{const saved=JSON.parse(storage.getItem(STATE_KEY));if(saved?.league)return {state:saved,reset:false};}catch{}for(const key of PREV_KEYS){try{const prev=JSON.parse(storage.getItem(key));storage.removeItem(key);if(prev?.league)return {state:upgradeToV4(prev),reset:false};}catch{}}return {state:initialState(),reset:legacy};}
export function movePlayer(state,id,group){const p=state.players.find(x=>x.id===id);if(!p||!['first','second','injured'].includes(group))return false;p.group=group;if(group==='injured'&&!p.injury){p.injury='상태 확인 중';p.days=7;}if(group!=='injured'){p.injury='';p.days=0;}if(group!=='first'){state.order=state.order.filter(x=>x!==id);Object.keys(state.field).forEach(k=>{if(state.field[k]===id)state.field[k]=null;});state.rotation=state.rotation.filter(x=>x!==id);state.bullpen=state.bullpen.filter(x=>x!==id);}else if(p.pitcher&&!state.rotation.includes(id)&&!state.bullpen.includes(id))state.bullpen.push(id);return true;}
export function assignField(state,id,pos){const p=state.players.find(x=>x.id===id);if(!p||p.pitcher||p.group!=='first'||!positions.includes(pos))return false;const old=state.field[pos],from=positions.find(k=>state.field[k]===id);state.field[pos]=id;if(from)state.field[from]=old||null;if(!state.order.includes(id)){const index=state.order.indexOf(old);if(index>=0)state.order[index]=id;else state.order.push(id);}return true;}
export function reorder(list,from,to){const a=list.indexOf(from),b=list.indexOf(to);if(a<0||b<0)return false;list.splice(b,0,list.splice(a,1)[0]);return true;}
export function swap(list,first,second){const a=list.indexOf(first),b=list.indexOf(second);if(a<0||b<0)return false;if(a===b)return true;[list[a],list[b]]=[list[b],list[a]];return true;}
export function assignPitcher(state,id,target,targetId){const p=state.players.find(x=>x.id===id);if(!p?.pitcher||p.group!=='first'||!['rotation','bullpen'].includes(target))return false;const source=state.rotation.includes(id)?'rotation':state.bullpen.includes(id)?'bullpen':null;if(source===target&&targetId)return reorder(state[target],id,targetId);const oldIndex=source?state[source].indexOf(id):-1,targetIndex=state[target].indexOf(targetId);if(targetIndex>=0){state[target][targetIndex]=id;if(source)state[source][oldIndex]=targetId;}else{if(target==='rotation'&&state.rotation.length>=Number.parseInt(state.strategy.size))return false;if(source)state[source].splice(oldIndex,1);state[target].push(id);}return true;}
export function schedule(month=3){return Array.from({length:new Date(2026,month,0).getDate()},(_,i)=>{const day=i+1,rest=new Date(2026,month-1,day).getDay()===1,op=1+Math.floor(i/3)%9,done=false;let ours=[0,1,0,2,0,0,1,0,i%3],theirs=[0,0,1,0,0,1,0,0,i%2];if(i%4===0)[ours,theirs]=[theirs,ours];return {day,month,rest,op,home:Math.floor(i/3)%2===0,done,ours,theirs,a:ours.reduce((a,b)=>a+b,0),b:theirs.reduce((a,b)=>a+b,0)};});}
